1	<script setup lang="ts">
2	/**
3	 * Single-slot notification for the latest accepted conversation action (UX-04).
4	 *
5	 * - Replaced, never stacked: the parent passes one slot or null.
6	 * - `role="status"` + polite live region; rendered in normal document flow so it
7	 *   never covers the focused row or the reader back path. The region stays
8	 *   mounted when empty (zero height, never `display:none`) so announcements are
9	 *   not dropped when content is inserted.
10	 * - Status text is derived from the matching Activity row on every refresh —
11	 *   the notice never invents a provider outcome. After a successful undo the
12	 *   parent reports the outcome (cancelled or the compensating rows) through
13	 *   `undone`, and the notice says Cancelled / Restored / the failure or
14	 *   uncertainty explicitly.
15	 * - The Undo button and Z hint are advisory only: they hide after the window
16	 *   passes, but the backend's typed `undo_unavailable` decision stays the
17	 *   authority and is surfaced through the same slot.
18	 */
19	import { computed } from 'vue';
20	import type { LastActionId, OperationSummaryLike } from '../composables/useMailbox';
21	import type { UndoOutcome } from '../lib/ipc/client';
22	
23	/** Skip-reason wording for partial group Undo results (UX-05 §5). */
24	const SKIP_REASON_LABELS: Record<string, string> = {
25	  acceptance_rejected: 'rejected at acceptance',
26	  failed: 'failed',
27	  outcome_unknown: 'outcome unknown',
28	  unknown_prior: 'unknown prior state',
29	  already_undone: 'already undone',
30	};
31	
32	export interface GroupNoticeView {
33	  count: number;
34	  /** Authoritative per-status member counts (accepted ≠ succeeded). */
35	  counts: { pending: number; confirmed: number; failed: number; rejected: number; unknown: number; cancelled: number };
36	  /** True while acceptance itself is unresolved (lost response, not yet committed). */
37	  acceptanceUnknown: boolean;
38	  /** True once any authoritative member status has landed. */
39	  statusKnown: boolean;
40	  /** ISO group-undo deadline from authoritative state; null when not undoable. */
41	  undoableUntil: string | null;
42	  hadWindow: boolean;
43	  /** True when the latest authoritative member-status read FAILED (distinct
44	   * from absence — never rendered as "Accepting…"). */
45	  statusError: boolean;
46	  /** Per-member group Undo outcomes, once the one attempt is accepted. */
47	  undone: {
48	    cancelled: number;
49	    compensating: number;
50	    skipped: number;
51	    skipReasons: Record<string, number>;
52	    /** CURRENT compensation outcomes, tracked separately from the original
53	     * execution statuses; a failed restoration is never hidden behind
54	     * permanent "restoring…" wording (§5/§6). */
55	    compensationOutcomes: { confirmed: number; failed: number; unknown: number; pending: number };
56	  } | null;
57	}
58	
59	const props = defineProps<{
60	  /** Null renders an empty live region so slot replacement stays announceable. */
61	  notice: {
62	    /** Human label of the performed action, e.g. "Mark Done (Archive)". */
63	    label: string;
64	    /** The setter action performed; selects the expired-recovery clause. */
65	    actionId: LastActionId;
66	    /** Subject when known; omitted (never a raw id) when unknown. */
67	    subject: string | null;
68	    operation: OperationSummaryLike | null;
69	    /** ISO deadline from the refreshed activity row; null when not undoable. */
70	    undoableUntil: string | null;
71	    /** True once this action had an undo window; gates the expired wording. */
72	    hadWindow: boolean;
73	    /** Set after a successful undo: outcome plus the refreshed compensating rows. */
74	    undone: { outcome: UndoOutcome; compensations: OperationSummaryLike[] } | null;
75	    /** Present when the slot holds a bulk group action instead of a single. */
76	    group?: GroupNoticeView | null;
77	  } | null;
78	  /** Advisory wall-clock milliseconds (App-owned timer); the backend decides eligibility. */
79	  now: number;
80	}>();
81	
82	const emit = defineEmits<{ undo: []; undoGroup: []; dismissGroup: [] }>();
83	
84	const isGroup = computed(() => !!props.notice?.group);
85	
86	/** Group status text: aggregate wording never hides partial failure (§6). */
87	const groupStatusText = computed(() => {
88	  const group = props.notice?.group ?? null;
89	  if (!group) return '';
90	  if (group.acceptanceUnknown) return 'Acceptance not yet known';
91	  if (group.statusError && !group.statusKnown) return 'Status check failed — will retry on next refresh';
92	  if (!group.statusKnown) return 'Accepting…';
93	  if (group.undone) {
94	    const undoneCount = group.undone.cancelled + group.undone.compensating;
95	    const reasonEntries = Object.entries(group.undone.skipReasons).filter(([, n]) => n > 0);
96	    const skipText = group.undone.skipped === 1 && reasonEntries.length === 1
97	      ? `1 skipped — ${SKIP_REASON_LABELS[reasonEntries[0]![0]!] ?? reasonEntries[0]![0]!}`
98	      : `${group.undone.skipped} skipped${reasonEntries.length ? ` — ${reasonEntries.map(([reason, n]) => `${n} ${SKIP_REASON_LABELS[reason] ?? reason}`).join(', ')}` : ''}`;
99	    const parts = [`Undo accepted for ${undoneCount} of ${group.count}`, skipText];
100	    const outcomes = group.undone.compensationOutcomes;
101	    if (outcomes.failed > 0) {
102	      parts.push(`restore failed for ${outcomes.failed} — see Activity`);
103	    }
104	    if (outcomes.unknown > 0) {
105	      parts.push(`restore outcome unknown for ${outcomes.unknown} — see Activity`);
106	    }
107	    if (outcomes.pending > 0) {
108	      parts.push(`restoring… (${outcomes.pending} pending)`);
109	    }
110	    if (outcomes.confirmed > 0) {
111	      parts.push(`restored (${outcomes.confirmed})`);
112	    }
113	    return parts.join('; ');
114	  }
115	  const c = group.counts;
116	  const parts: string[] = [];
117	  if (c.confirmed > 0) parts.push(`${c.confirmed} confirmed`);
118	  if (c.pending > 0) parts.push(`${c.pending} pending`);
119	  if (c.failed > 0) parts.push(`${c.failed} failed`);
120	  if (c.unknown > 0) parts.push(`${c.unknown} outcome unknown`);
121	  if (c.cancelled > 0) parts.push(`${c.cancelled} cancelled`);
122	  if (c.rejected > 0) parts.push(`${c.rejected} rejected at acceptance`);
123	  return parts.length > 0 ? `Accepted · ${parts.join(', ')}` : 'Accepted';
124	});
125	
126	const groupUndoVisible = computed(() => {
127	  const group = props.notice?.group ?? null;
128	  if (!group || group.undone || group.acceptanceUnknown) return false;
129	  const until = group.undoableUntil;
130	  return until !== null && Date.parse(until) > props.now;
131	});
132	
133	const groupUndoExpired = computed(() => {
134	  const group = props.notice?.group ?? null;
135	  if (!group || group.undone || group.acceptanceUnknown || !group.hadWindow) return false;
136	  const until = group.undoableUntil;
137	  return until === null || Date.parse(until) <= props.now;
138	});
139	
140	/** Recovery clause after an expired window, per the action that was undone. */
141	const UNDO_EXPIRED_RECOVERY: Record<LastActionId, string> = {
142	  archive: 'Mark Not Done restores the whole conversation to Inbox',
143	  unarchive: 'Mark Done archives the whole conversation',
144	  read: 'use the opposite read control',
145	  unread: 'use the opposite read control',
146	  star: 'use Unstar',
147	  unstar: 'use Star',
148	};
149	
150	const statusText = computed(() => {
151	  const undone = props.notice?.undone ?? null;
152	  if (undone) {
153	    if (undone.outcome === 'cancelled') return 'Cancelled';
154	    const statuses = undone.compensations.map((op) => op.status);
155	    if (statuses.includes('failed')) return 'Restore failed — see Activity';
156	    if (statuses.includes('outcome_unknown')) return 'Restore outcome unknown — see Activity';
157	    if (statuses.length > 0 && statuses.every((status) => status === 'confirmed')) return 'Restored';
158	    // Compensations not landed/confirmed yet (or not visible in activity yet).
159	    return 'Restoring…';
160	  }
161	  const status = props.notice?.operation?.status;
162	  switch (status) {
163	    case 'queued':
164	    case 'applying':
165	      return 'Accepted locally, not yet confirmed';
166	    case 'confirmed':
167	      return 'Confirmed';
168	    case 'failed':
169	      return 'Failed — restored, see Activity';
170	    case 'outcome_unknown':
171	      return 'Outcome unknown — see Activity';
172	    case 'cancelled':
173	      return 'Cancelled';
174	    default:
175	      // The Activity row has not landed yet; acceptance is the only known fact.
176	      return 'Accepted locally, not yet confirmed';
177	  }
178	});
179	
180	const undoVisible = computed(() => {
181	  const until = props.notice?.undoableUntil;
182	  if (!until || props.notice?.undone) return false;
183	  return Date.parse(until) > props.now;
184	});
185	
186	const undoExpired = computed(() => {
187	  const status = props.notice?.operation?.status;
188	  // Never after an undo: the original op row can stay `confirmed` while the
189	  // compensations fail — the failure wording, not expiry, is the story then.
190	  return !props.notice?.undone && !!props.notice?.hadWindow && !undoVisible.value
191	    && (status === 'queued' || status === 'applying' || status === 'confirmed');
192	});
193	
194	const undoExpiredText = computed(() => {
195	  const actionId = props.notice?.actionId ?? 'archive';
196	  return `Undo expired — ${UNDO_EXPIRED_RECOVERY[actionId]}`;
197	});
198	
199	const truncatedSubject = computed(() => {
200	  const subject = props.notice?.subject ?? '';
201	  return subject.length > 60 ? `${subject.slice(0, 60)}…` : subject;
202	});
203	</script>
204	
205	<template>
206	  <div
207	    class="action-notice"
208	    :class="{ 'action-notice-empty': !notice }"
209	    role="status"
210	    aria-live="polite"
211	    data-test="action-notice"
212	  >
213	    <!-- Bulk group slot (UX-05): one identity, per-status counts, partial undo. -->
214	    <template v-if="notice && isGroup">
215	      <p class="action-notice-text" data-test="action-notice-text">
216	        <span class="action-notice-label" data-test="action-notice-label">{{ notice.label }} · {{ notice.group!.count }} conversations</span>
217	        <span class="action-notice-status" data-test="action-notice-status">{{ groupStatusText }}</span>
218	        <span v-if="notice.group!.acceptanceUnknown" class="action-notice-expired" data-test="action-notice-acceptance-unknown">
219	          Nothing is known to have committed; checking again replays this exact request.
220	        </span>
221	        <span v-else-if="groupUndoExpired" class="action-notice-expired" data-test="action-notice-expired">Undo expired — recover individual members from Activity</span>
222	      </p>
223	      <span v-if="notice.group!.acceptanceUnknown" class="action-notice-undo">
224	        <button type="button" data-test="action-notice-recover-acceptance" @click="emit('undoGroup')">Check acceptance</button>
225	        <!-- No Dismiss while acceptance is unresolved: the original request id
226	             and command must be kept and the mutation fence held until
227	             authoritative resolution (§3.3/§4.3). -->
228	      </span>
229	      <span v-else-if="groupUndoVisible" class="action-notice-undo">
230	        <button type="button" data-test="action-notice-undo-group" @click="emit('undoGroup')">Undo</button>
231	        <kbd data-test="action-notice-hint">Z</kbd>
232	      </span>
233	    </template>
234	    <template v-else-if="notice">
235	      <p class="action-notice-text" data-test="action-notice-text">
236	        <span class="action-notice-label" data-test="action-notice-label">
237	          {{ notice.label }}<template v-if="notice.subject"> · {{ truncatedSubject }}</template>
238	        </span>
239	        <span class="action-notice-status" data-test="action-notice-status">{{ statusText }}</span>
240	        <span v-if="undoExpired" class="action-notice-expired" data-test="action-notice-expired">{{ undoExpiredText }}</span>
241	      </p>
242	      <span v-if="undoVisible" class="action-notice-undo">
243	        <button type="button" data-test="action-notice-undo" @click="emit('undo')">Undo</button>
244	        <kbd data-test="action-notice-hint">Z</kbd>
245	      </span>
246	    </template>
247	  </div>
248	</template>
